"""Italiano — Corano (quran_001 … quran_080)."""

T = {
"quran_001": ("Qual è il nome del primo capitolo (sura) del Corano?", ["Al-Fatiha", "Al-Baqara", "Al-Ikhlas", "An-Nas"], "Al-Fatiha, «L'Aprente», è il primo capitolo del Corano."),
"quran_002": ("Quanti capitoli (sure) contiene il Corano?", ["114", "99", "100", "120"], "Il Corano è composto da 114 sure."),
"quran_003": ("Qual è la sura più lunga del Corano?", ["Al-Baqara", "Al-Fatiha", "Al-Kawthar", "Al-'Asr"], "Al-Baqara è la sura più lunga del Corano, con 286 versetti."),
"quran_004": ("Qual è la sura più breve del Corano?", ["Al-Kawthar", "Al-Ikhlas", "Al-'Asr", "An-Nasr"], "Al-Kawthar, con 3 versetti, è la sura più breve del Corano."),
"quran_005": ("In quale lingua fu rivelato il Corano?", ["Arabo", "Aramaico", "Ebraico", "Persiano"], "Il Corano afferma esplicitamente di essere stato rivelato in lingua araba."),
"quran_006": ("Qual è il nome della 19ª sura, che porta il nome della madre di Isa?", ["Maryam", "Yusuf", "Al-Kahf", "Ta-Ha"], "La 19ª sura del Corano si chiama Maryam, dal nome della madre del profeta Isa."),
"quran_007": ("Come si chiama un capitolo del Corano?", ["Una sura", "Un hadith", "Un juz'", "Un tafsir"], "Il Corano è diviso in capitoli chiamati sure."),
"quran_008": ("Come si chiama un versetto del Corano?", ["Un'aya", "Una sura", "Un hadith", "Un ruku'"], "Ogni versetto del Corano si chiama aya, che significa «segno»."),
"quran_009": ("Quale sura va recitata obbligatoriamente in ogni unità (rak'a) della preghiera?", ["Al-Fatiha", "Al-Ikhlas", "Al-Kawthar", "Al-Fil"], "La recitazione di Al-Fatiha è un pilastro della preghiera riportato in un hadith autentico."),
"quran_010": ("A chi fu rivelato il Corano?", ["Al Profeta Muhammad ﷺ", "Al Profeta Musa", "Al Profeta Isa", "Al Profeta Dawud"], "Il Corano fu rivelato al Profeta Muhammad ﷺ tramite l'angelo Jibril."),
"quran_011": ("Come si chiama il celebre versetto 255 della sura Al-Baqara?", ["Ayat al-Kursi (il Versetto del Trono)", "Ayat an-Nur", "Ayat as-Siyam", "Ayat ad-Dayn"], "Il versetto 2:255, Ayat al-Kursi, descrive la grandezza di Allah: «Allah, non c'è dio all'infuori di Lui, il Vivente…»"),
"quran_012": ("Quale sura non inizia con «Bismillah ir-Rahman ir-Rahim»?", ["At-Tawba", "Al-Fatiha", "Ya-Sin", "Al-Kahf"], "At-Tawba (sura 9) è l'unica sura che non si apre con la basmala."),
"quran_013": ("Qual è il tema del versetto più lungo del Corano (2:282)?", ["La registrazione dei debiti", "Il pellegrinaggio", "Il digiuno", "L'eredità"], "Il versetto più lungo del Corano insegna a mettere per iscritto i debiti e a prendere testimoni: l'onestà è protetta."),
"quran_014": ("Con quale parola iniziano i primissimi versetti rivelati del Corano?", ["Iqra' (Leggi!)", "Qul (Di'!)", "Sabbih (Glorifica!)", "Kutiba (È stato prescritto)"], "I primi versetti rivelati iniziano con «Iqra'»: «Leggi, nel nome del tuo Signore che ha creato.»"),
"quran_015": ("Secondo il Corano, la Notte del Destino è migliore di quanti mesi?", ["Mille mesi", "Cento mesi", "Dodici mesi", "Quaranta mesi"], "«La Notte del Destino è migliore di mille mesi»: una notte di Ramadan che vale più di una vita di adorazione."),
"quran_016": ("Come si chiamano le ultime due sure, Al-Falaq e An-Nas, recitate per protezione?", ["Al-Mu'awwidhatan (le due protettrici)", "Az-Zahrawan", "Al-Mufassal", "As-Sab' at-Tiwal"], "Al-Falaq e An-Nas sono chiamate «al-mu'awwidhatan»: si recitano per chiedere la protezione di Allah."),
"quran_017": ("In quante parti (juz') è tradizionalmente diviso il Corano?", ["30", "10", "60", "114"], "Il Corano è diviso in 30 juz', il che aiuta a completarlo in un mese, ad esempio durante il Ramadan."),
"quran_018": ("Quanti versetti contiene la sura Al-Fatiha?", ["7", "3", "10", "14"], "Al-Fatiha ha sette versetti, recitati in ogni unità della preghiera."),
"quran_019": ("Quale sura porta il nome di un metallo?", ["Al-Hadid (Il Ferro)", "An-Nur (La Luce)", "Ar-Ra'd (Il Tuono)", "Ad-Dukhan (Il Fumo)"], "La sura 57 si chiama Al-Hadid: «Abbiamo fatto scendere il ferro, in cui vi è grande forza e benefici per gli uomini.»"),
"quran_020": ("Quale storia il Corano chiama «la più bella delle storie»?", ["La storia di Yusuf", "La storia di Nuh", "La storia della gente della caverna", "La storia dell'elefante"], "«Ti raccontiamo la più bella delle storie»: così si apre la storia di Yusuf."),
"quran_021": ("Quanti versetti contiene Al-Baqara, la sura più lunga?", ["286", "114", "200", "365"], "Al-Baqara ha 286 versetti: la sura più lunga del Corano."),
"quran_022": ("Quale breve sura proclama: «Di': Egli è Allah, l'Unico»?", ["Al-Ikhlas", "Al-Falaq", "An-Nas", "Al-Kawthar"], "Al-Ikhlas proclama la perfetta unicità di Allah in quattro versetti."),
"quran_023": ("Nell'arco di circa quanti anni fu rivelato il Corano?", ["23 anni", "1 anno", "10 anni", "40 anni"], "Il Corano fu rivelato gradualmente in circa 23 anni, alla Mecca e poi a Medina."),
"quran_024": ("Secondo il Corano, quale fu la prima Casa stabilita perché gli uomini adorassero Allah?", ["La Ka'ba, a Bakka (La Mecca)", "La moschea di Quba", "Bayt al-Maqdis", "La moschea del Profeta ﷺ"], "«La prima Casa stabilita per l'umanità è quella di Bakka, benedetta…»: la Ka'ba alla Mecca."),
"quran_025": ("Quale sura porta il nome dell'elefante?", ["Al-Fil", "An-Nahl", "An-Naml", "Al-Baqara"], "La sura 105, Al-Fil («L'Elefante»), ricorda l'esercito di elefanti di Abraha, fermato davanti alla Mecca."),
"quran_026": ("La sura An-Nahl porta il nome di quale insetto?", ["L'ape", "La formica", "Il ragno", "La mosca"], "An-Nahl significa «le api»; in essa Allah ispira l'ape a costruire le sue dimore (16:68)."),
"quran_027": ("Quale sura porta il nome della formica?", ["An-Naml", "An-Nahl", "Al-'Ankabut", "Al-An'am"], "An-Naml («Le Formiche», sura 27) racconta della formica che avvertì le compagne all'avvicinarsi dell'esercito di Sulayman."),
"quran_028": ("Nella sura Al-'Ankabut, a che cosa il Corano paragona coloro che prendono protettori all'infuori di Allah?", ["A un ragno che costruisce una casa fragile", "A un'ape che costruisce l'alveare", "A una formica che accumula cibo", "A un cane ansimante"], "«La più fragile delle case è la casa del ragno» (29:41), che dà il nome alla sura."),
"quran_029": ("La sura Al-Baqara porta il nome di quale animale?", ["La vacca", "Il cammello", "Il cavallo", "La pecora"], "Al-Baqara («La Vacca») ricorda la vacca che i Figli d'Israele furono comandati di sacrificare (2:67)."),
"quran_030": ("Che cosa significa il titolo della sura 6, Al-An'am?", ["Il bestiame", "Gli uccelli", "I giardini", "Le stelle"], "Al-An'am significa «il bestiame»; la sura confuta le regole inventate dai pagani sugli animali."),
"quran_031": ("Quale versetto si ripete molte volte nella sura Ar-Rahman?", ["«Quale dei favori del vostro Signore negherete?»", "«Allah è il più Grande»", "«Di': Egli è Allah, Uno»", "«Lode ad Allah»"], "Questo ritornello («Fa-bi-ayyi ala'i rabbikuma tukadhdhiban») ricorre 31 volte nella sura 55."),
"quran_032": ("Secondo la sura Al-Kahf, per quanto tempo dormirono i Compagni della Caverna?", ["Trecento anni, più nove", "Cento anni", "Quarant'anni", "Mille anni"], "«Rimasero nella loro caverna trecento anni, e ne aggiunsero nove» (18:25)."),
"quran_033": ("Quale animale era con i Compagni della Caverna?", ["Un cane", "Un gatto", "Un asino", "Una capra"], "«Il loro cane stendeva le zampe anteriori all'ingresso» (18:18)."),
"quran_034": ("Contro quali popoli Dhul-Qarnayn costruì una barriera, secondo Al-Kahf?", ["Ya'juj e Ma'juj (Gog e Magog)", "'Ad e Thamud", "I Romani", "I Persiani"], "Un popolo gli chiese protezione da Ya'juj e Ma'juj; egli innalzò un bastione di ferro e rame (18:94-96)."),
"quran_035": ("Quale versetto inizia con «Allah è la Luce dei cieli e della terra»?", ["Il Versetto della Luce (An-Nur 24:35)", "Il Versetto del Trono", "Il Versetto del Debito", "Il Versetto della Caverna"], "«Ayat an-Nur» paragona la Sua luce a una nicchia in cui brilla una lampada (24:35)."),
"quran_036": ("Secondo un hadith in al-Bukhari, quale sura equivale a un terzo del Corano?", ["Al-Ikhlas", "Al-Fatiha", "Ya-Sin", "Al-Kahf"], "Il Profeta ﷺ disse di «Qul huwa Allahu ahad» che «equivale a un terzo del Corano»."),
"quran_037": ("Quale versetto il Profeta ﷺ indicò come il più grande del Corano, secondo Sahih Muslim?", ["Il Versetto del Trono (Ayat al-Kursi)", "Il primo versetto di Al-Fatiha", "L'ultimo versetto di Al-Baqara", "Il Versetto della Luce"], "Chiese a Ubayy ibn Ka'b quale versetto fosse il più grande; Ubayy rispose Ayat al-Kursi, e il Profeta ﷺ si congratulò con lui."),
"quran_038": ("Quale nemico del Profeta ﷺ è nominato nella sura Al-Masad?", ["Abu Lahab", "Abu Jahl", "Abu Sufyan", "Al-Walid"], "«Periscano le mani di Abu Lahab» (111:1): questo zio del Profeta ﷺ lo combatté apertamente."),
"quran_039": ("Come termina la sura Al-Kafirun?", ["«A voi la vostra religione, e a me la mia»", "«Allah è il più Grande»", "«E nessuno è pari a Lui»", "«Dal male dell'invidioso»"], "«Lakum dinukum wa liya din» (109:6) afferma la netta separazione tra l'Islam e l'idolatria."),
"quran_040": ("Di che cosa parla la sura An-Nasr?", ["Dell'aiuto di Allah e della gente che entra a frotte nella religione", "Della creazione del cielo", "Del digiuno di Ramadan", "Della storia di Yusuf"], "«Quando giungono l'aiuto di Allah e la vittoria, e vedi la gente entrare a frotte nella religione di Allah» (110:1-2)."),
"quran_041": ("Secondo la sura Al-'Asr, chi è salvato dalla perdita?", ["Coloro che credono, fanno il bene e si esortano a vicenda alla verità e alla pazienza", "Coloro che sono ricchi", "Coloro che sono forti", "Coloro che viaggiano"], "«L'uomo è in perdita, tranne coloro che credono, compiono opere buone e si esortano a vicenda alla verità e alla pazienza» (103:2-3)."),
"quran_042": ("Nella sura Al-Ma'un, che cosa fa «colui che nega il Giudizio»?", ["Respinge l'orfano e non esorta a nutrire il povero", "Distrugge le moschee", "Rifiuta di viaggiare", "Mente sulla sua ricchezza"], "«È colui che respinge l'orfano e non esorta a nutrire il povero» (107:2-3)."),
"quran_043": ("Secondo i primi versetti rivelati (Al-'Alaq), da che cosa Allah creò l'uomo?", ["Da un'aderenza ('alaq)", "Dalla luce", "Dal fuoco", "Dal vento"], "«Leggi, nel nome del tuo Signore che ha creato, che ha creato l'uomo da un'aderenza» (96:1-2)."),
"quran_044": ("A che cosa si riferisce l'espressione coranica «i sette versetti ripetuti» (as-sab' al-mathani)?", ["Ad Al-Fatiha", "Alle sette sure più lunghe", "Ad Ayat al-Kursi", "Agli ultimi sette versetti del Corano"], "«Ti abbiamo dato sette dei ripetuti e il grande Corano» (15:87): Al-Fatiha, recitata in ogni rak'a."),
"quran_045": ("Che cosa significa «Al-Furqan», uno dei nomi del Corano?", ["Il Criterio (tra verità e falsità)", "La Luce", "Il Ricordo", "La Guarigione"], "«Benedetto Colui che ha fatto scendere il Furqan sul Suo servo» (25:1): il Libro che separa la verità dalla falsità."),
"quran_046": ("Su che cosa giura Allah all'inizio della sura At-Tur?", ["Sul Monte (Tur)", "Sul sole", "Sul fico", "Sulla notte"], "«Per il Monte! E per un Libro scritto…» (52:1-2): il Tur è la montagna dove Musa ricevette la rivelazione."),
"quran_047": ("Che cosa significa «An-Najm», il titolo della sura 53?", ["La stella", "La luna", "Il sole", "L'alba"], "«Per la stella quando tramonta!» (53:1)."),
"quran_048": ("Secondo la sura Al-Qadr, chi discende durante la Notte del Destino?", ["Gli angeli e lo Spirito (Jibril)", "I profeti", "I jinn", "I venti"], "«Gli angeli e lo Spirito vi discendono con il permesso del loro Signore» (97:4)."),
"quran_049": ("Secondo il Corano, che cos'è il Corano per i credenti?", ["Una guarigione e una misericordia", "Solo un poema", "Un libro di storia", "Un calendario"], "«Facciamo scendere del Corano ciò che è guarigione e misericordia per i credenti» (17:82)."),
"quran_050": ("Quale sfida lancia il Corano a chi dubita della sua origine divina?", ["Produrre una sola sura simile", "Recitare tutto il Corano a memoria", "Tradurre il Corano", "Costruire una moschea"], "«Se avete dubbi su ciò che abbiamo fatto scendere, producete allora una sura simile» (2:23)."),
"quran_051": ("Quale sura è chiamata «Umm al-Qur'an» (la Madre del Corano)?", ["Al-Fatiha", "Al-Baqara", "Ya-Sin", "Al-Ikhlas"], "Il Profeta ﷺ disse: «Umm al-Qur'an è i sette versetti ripetuti e il grande Corano.»"),
"quran_052": ("Che cos'è una sura «meccana»?", ["Una sura rivelata prima della Hijra", "Una sura rivelata a Medina", "Una sura sulla Ka'ba", "Una sura molto breve"], "Gli studiosi classificano le sure per periodo: prima della migrazione a Medina (meccane) o dopo (medinesi)."),
"quran_053": ("Quante sure iniziano con le lettere «Alif, Lam, Mim»?", ["Sei", "Due", "Dieci", "Una"], "Al-Baqara, Al 'Imran, Al-'Ankabut, Ar-Rum, Luqman e As-Sajda si aprono con «Alif, Lam, Mim»."),
"quran_054": ("Come si chiamano le lettere isolate che aprono alcune sure (Alif Lam Mim, Ya Sin, Qaf…)?", ["Le lettere staccate (al-huruf al-muqatta'a)", "I versetti abrogati", "Le lettere solari", "Le lettere del tajwid"], "Ventinove sure si aprono con queste lettere, il cui pieno significato è noto solo ad Allah."),
"quran_055": ("Quale sura porta il nome del Profeta Muhammad ﷺ?", ["La sura 47, Muhammad", "La sura 1, Al-Fatiha", "La sura 36, Ya-Sin", "La sura 112, Al-Ikhlas"], "La sura 47 si chiama «Muhammad»; menziona il suo nome nel versetto 2."),
"quran_056": ("Qual è il primo consiglio di Luqman a suo figlio, citato nel Corano?", ["Non associare nulla ad Allah", "Studiare le stelle", "Diventare mercante", "Viaggiare lontano"], "«Figlio mio, non associare nulla ad Allah; in verità, l'associazione è un'enorme ingiustizia» (31:13)."),
"quran_057": ("Con quale altro nome è conosciuta la sura At-Tawba?", ["Bara'a (la Dissociazione)", "An-Nur", "Al-Anfal", "Al-Fath"], "La sua prima parola è «Bara'a»: una dichiarazione di dissociazione da parte di Allah e del Suo Messaggero verso gli idolatri (9:1)."),
"quran_058": ("Quale sura inizia con le due lettere «Ya, Sin»?", ["Ya-Sin (sura 36)", "Ta-Ha", "Qaf", "Sad"], "La sura 36 si apre con «Ya-Sin. Per il saggio Corano!»"),
"quran_059": ("Che cosa significa «Al-Mulk», il titolo della sura 67?", ["La Sovranità / il Regno", "La Luce", "Il Viaggio", "La Vittoria"], "«Benedetto Colui nella cui mano è la Sovranità (al-Mulk)» (67:1)."),
"quran_060": ("Qual è l'ultima sura del Corano?", ["An-Nas", "Al-Falaq", "Al-Ikhlas", "Al-Fatiha"], "An-Nas («Gli Uomini»), sura 114, chiude il Corano: «Di': mi rifugio nel Signore degli uomini»."),
"quran_061": ("Come inizia la sura Al-Falaq?", ["«Di': mi rifugio nel Signore dell'alba»", "«Di': Egli è Allah, Uno»", "«Per il tempo!»", "«Lode ad Allah»"], "«Qul a'udhu bi-rabbi-l-falaq» (113:1): Al-Falaq significa l'alba."),
"quran_062": ("Quali due colline il Corano nomina tra i «simboli di Allah»?", ["As-Safa e Al-Marwa", "Uhud e Thawr", "'Arafat e Mina", "Hira' e Abu Qubays"], "«As-Safa e Al-Marwa sono tra i simboli di Allah» (2:158): il sa'y del pellegrinaggio si percorre tra di esse."),
"quran_063": ("Chi è l'unica donna menzionata per nome nel Corano?", ["Maryam", "Khadija", "Asiya", "Hajar"], "Maryam, madre di 'Isa, è nominata in diverse sure, e un'intera sura porta il suo nome."),
"quran_064": ("Chi è l'unico compagno del Profeta ﷺ nominato nel Corano?", ["Zayd ibn Haritha", "Abu Bakr", "'Umar", "'Ali"], "«Quando Zayd ebbe concluso il suo rapporto con lei…» (33:37): Zayd, lo schiavo liberato del Profeta, è l'unico compagno nominato."),
"quran_065": ("Chi erano Harut e Marut, menzionati nella sura Al-Baqara?", ["Due angeli inviati a Babilonia", "Due profeti", "Due re d'Egitto", "Due compagni"], "«…ciò che fu fatto scendere ai due angeli Harut e Marut a Babilonia» (2:102): avvertivano che la magia era una prova."),
"quran_066": ("Secondo il Corano, chi è il più nobile agli occhi di Allah?", ["Il più timorato", "Il più ricco", "Il più forte", "Il più famoso"], "«Il più nobile tra voi agli occhi di Allah è il più timorato» (49:13)."),
"quran_067": ("A che cosa si riferisce «Al-Waqi'a», il titolo della sura 56?", ["All'Evento inevitabile (il Giorno della Resurrezione)", "Alla carovana", "Alla formica", "Al viaggio notturno"], "«Quando accadrà l'Evento…» (56:1): la sura descrive i tre gruppi dell'Ultimo Giorno."),
"quran_068": ("Su quale oggetto giura Allah all'inizio della sura Al-Qalam?", ["Sul calamo", "Sulla spada", "Sulla bilancia", "Sulla lampada"], "«Nun. Per il calamo e ciò che scrivono!» (68:1)."),
"quran_069": ("Come si apre la sura Al-Fajr?", ["Con un giuramento sull'alba e su dieci notti", "Con un giuramento sul fico", "Con una storia di Yusuf", "Con la sola basmala"], "«Per l'alba! E per le dieci notti!» (89:1-2)."),
"quran_070": ("Su quale corpo celeste giura Allah all'inizio della sura Ash-Shams?", ["Il sole", "Solo la luna", "Le stelle", "I pianeti"], "«Per il sole e il suo splendore!» (91:1); Ash-Shams significa «il sole»."),
"quran_071": ("Quale sura si apre così: «Non è forse trascorso per l'uomo un periodo di tempo in cui non era una cosa menzionata?»", ["Al-Insan (sura 76)", "Al-Kahf", "Al-Hajj", "Al-Fatiha"], "Al-Insan («L'Uomo»), detta anche Ad-Dahr, ricorda che l'uomo non era nulla prima della sua creazione (76:1)."),
"quran_072": ("Secondo il Corano, per che cosa Allah ha reso facile il Corano?", ["Per il ricordo e la memorizzazione", "Per il commercio", "Per la traduzione", "Per l'oblio"], "«Abbiamo reso facile il Corano per il ricordo; c'è qualcuno che ne tragga ammonimento?» (54:17), ripetuto quattro volte nella sura."),
"quran_073": ("Quale segno menziona la sura Al-Qamar nel suo primissimo versetto?", ["La luna si è spaccata", "Il sole si è spento", "Il mare si è aperto", "La montagna ha parlato"], "«L'Ora si avvicina e la luna si è spaccata» (54:1): un segno mostrato ai Meccani."),
"quran_074": ("Perché il Corano fu rivelato gradualmente e non tutto in una volta, secondo il Corano stesso?", ["Per rafforzare il cuore del Profeta ﷺ", "Perché era troppo lungo", "Per nasconderlo ai nemici", "A causa dei viaggi"], "«Così, per rafforzare con esso il tuo cuore, e lo abbiamo recitato con recitazione accurata» (25:32)."),
"quran_075": ("Quali sure recitava il Profeta ﷺ nelle sue mani ogni notte prima di dormire, secondo 'A'isha?", ["Al-Ikhlas, Al-Falaq e An-Nas", "Al-Fatiha e Al-Baqara", "Ya-Sin e Al-Mulk", "Al-Kahf e Maryam"], "Soffiava nelle mani recitando le tre sure «Qul», poi le passava sul corpo, tre volte."),
"quran_076": ("Come si chiama la prostrazione fatta recitando certi versetti del Corano?", ["La prostrazione della recitazione (sujud at-tilawa)", "La prostrazione della dimenticanza", "La prostrazione di ringraziamento", "Il ruku'"], "Il Corano contiene versetti di prostrazione, come l'ultimo versetto di Al-'Alaq: «prostrati e avvicinati» (96:19)."),
"quran_077": ("Come si chiama la scienza delle regole per pronunciare correttamente il Corano?", ["Tajwid", "Tafsir", "Fiqh", "Sira"], "Il tajwid insegna a pronunciare ogni lettera dal suo punto di articolazione, con le sue qualità."),
"quran_078": ("Come si chiama chi ha memorizzato tutto il Corano?", ["Un hafiz", "Un imam", "Un muezzin", "Un mufti"], "Hafiz significa «colui che custodisce»: porta l'intero Corano nella sua memoria."),
"quran_079": ("Come si chiama la copia scritta del Corano?", ["Un mushaf", "Un hadith", "Un juz'", "Un minbar"], "Il mushaf è il Corano raccolto tra due copertine; un juz' è una delle sue trenta parti."),
"quran_080": ("In quale sura la basmala compare due volte?", ["An-Naml", "Al-Fatiha", "At-Tawba", "Al-Baqara"], "Oltre che nella sua apertura, An-Naml cita la basmala all'inizio della lettera di Sulayman alla regina di Saba' (27:30)."),
}
